INSERT INTO temp_vocab_seed (vocab_id, example_jp, example_vi, example_romaji) VALUES
(1, '新しい「東」を購入しました。', 'Tôi đã mua một đông mới.', 'Atarashii ''higashi'' o kounyuu shimashita.'),
(2, '今日はとても「私」天気ですね。', 'Hôm nay thời tiết thật là tôi nhỉ.', 'Kyou wa totemo ''watakushi'' tenki desu ne.'),
(3, '一日の終わりに温かいお茶を飲んでリラックスします。', 'Cuối một ngày tôi uống tách trà ấm để thư giãn.', 'Ichinichi no owari ni atatakai ocha o nonde rirakkusu shimasu.'),
(4, '一人で悩まないで、何でも気軽に相談してください。', 'Đừng chịu đựng lo lắng một mình, hãy cứ thoải mái tâm sự nhé.', 'Hitori de nayamanaide, nan demo kigaru ni soudan shite kudasai.'),
(5, '「暇」ものが好きです。', 'Tôi thích những thứ thời gian rảnh rỗi.', '''hima'' mono ga suki desu.'),
(6, '今日はとても「入口」天気ですね。', 'Hôm nay thời tiết thật là cổng vào nhỉ.', 'Kyou wa totemo ''iriguchi'' tenki desu ne.'),
(7, '寒い日は温かいお風呂に入るのが一番気持ちいいです。', 'Ngày trời lạnh thì ngâm mình trong bồn tắm ấm là dễ chịu nhất.', 'Samui hi wa atatakai ofuro ni hairu no ga ichiban kimochiii desu.'),
(8, 'この本はとても「甘い」内容です。', 'Cuốn sách này có nội dung rất ngon ngọt.', 'Kono hon wa totemo ''amai'' naiyou desu.'),
(9, '「上手」ものが好きです。', 'Tôi thích những thứ lời tâng bốc.', '''jouzu'' mono ga suki desu.'),
(10, '「塩」の使い方をマスターしましょう。', 'Hãy cùng nắm vững cách sử dụng của muối nhé.', '''shio'' no tsukaikata o masukaa shimashou.'),
(11, 'その景色は本当に「黄色」と感じました。', 'Tôi cảm thấy khung cảnh đó thực sự rất màu vàng.', 'Sono keshiki wa hontou ni ''kiiro'' to kanjimashita.'),
(12, '「弟」について詳しく調べました。', 'Tôi đã tìm hiểu rất kỹ lưỡng về bào đệ.', '''otouto'' ni tsuite kuwashiku shirabemashita.'),
(13, '新しい「門」を購入しました。', 'Tôi đã mua một cổng mới.', 'Atarashii ''mon'' o kounyuu shimashita.'),
(14, '「眼鏡」の使い方をマスターしましょう。', 'Hãy cùng nắm vững cách sử dụng của kính nhé.', '''megane'' no tsukaikata o masukaa shimashou.'),
(15, '日曜日の午後、先輩が家に遊びに来ました。', 'Chiều chủ nhật, tiền bối đã đến nhà tôi chơi.', 'Nichiyoubi no gogo, senpai ga ie ni asobi ni kimashita.'),
(16, '「戸」について詳しく調べました。', 'Tôi đã tìm hiểu rất kỹ lưỡng về cánh cửa.', '''to'' ni tsuite kuwashiku shirabemashita.'),
(17, '「次」ものが好きです。', 'Tôi thích những thứ lần sau.', '''tsugi'' mono ga suki desu.'),
(18, '今日はとても「丈夫」天気ですね。', 'Hôm nay thời tiết thật là sự bền nhỉ.', 'Kyou wa totemo ''joubu'' tenki desu ne.'),
(19, '「人」は日常生活でよく使われます。', 'người thường xuyên được sử dụng trong đời sống hàng ngày.', '''hito'' wa nichijou seikatsu de yoku tsukawaremasu.'),
(20, '「前」について詳しく調べました。', 'Tôi đã tìm hiểu rất kỹ lưỡng về tiền.', '''mae'' ni tsuite kuwashiku shirabemashita.'),
(21, '新しい「誰」を購入しました。', 'Tôi đã mua một ai mới.', 'Atarashii ''dare'' o kounyuu shimashita.'),
(22, '今日はとても「体」天気ですね。', 'Hôm nay thời tiết thật là cơ thể nhỉ.', 'Kyou wa totemo ''karada'' tenki desu ne.'),
(23, '「店」は日常生活でよく使われます。', 'cửa hàng thường xuyên được sử dụng trong đời sống hàng ngày.', '''mise'' wa nichijou seikatsu de yoku tsukawaremasu.'),
(24, '毎日「止まる」練習を続けています。', 'Tôi duy trì việc luyện tập dừng lại mỗi ngày.', 'Mainichi ''tomaru'' renshuu o tsuzukete imasu.'),
(25, '「七日」ことはとても大切です。', 'Việc 7 ngày là điều rất quan trọng.', '''nanoka'' koto wa totemo taisetsu desu.'),
(26, '「南」の使い方をマスターしましょう。', 'Hãy cùng nắm vững cách sử dụng của nam nhé.', '''minami'' no tsukaikata o masukaa shimashou.'),
(27, 'その景色は本当に「悪い」と感じました。', 'Tôi cảm thấy khung cảnh đó thực sự rất còm.', 'Sono keshiki wa hontou ni ''warui'' to kanjimashita.'),
(28, '「二人」について詳しく調べました。', 'Tôi đã tìm hiểu rất kỹ lưỡng về Hai người.', '''futari'' ni tsuite kuwashiku shirabemashita.'),
(29, '新しい「灰皿」を購入しました。', 'Tôi đã mua một gạt tàn mới.', 'Atarashii ''haizara'' o kounyuu shimashita.'),
(30, '上手に「弾く」ことができますか。', 'Bạn có thể gảy một cách thành thạo được không?', 'Jouzu ni ''hiku'' koto ga dekimasu ka.'),
(31, 'これから「始め」準備を始めましょう。', 'Từ bây giờ chúng ta hãy bắt đầu chuẩn bị để lúc đầu nhé.', 'Korekara ''hajime'' junbi o hajimemashou.'),
(32, '「万」について詳しく調べました。', 'Tôi đã tìm hiểu rất kỹ lưỡng về mười nghìn.', '''man'' ni tsuite kuwashiku shirabemashita.'),
(33, '新しい「三」を購入しました。', 'Tôi đã mua một ba mới.', 'Atarashii ''san'' o kounyuu shimashita.'),
(34, '「六」の使い方をマスターしましょう。', 'Hãy cùng nắm vững cách sử dụng của số sáu nhé.', '''roku'' no tsukaikata o masukaa shimashou.'),
(35, 'これから「一昨日」準備を始めましょう。', 'Từ bây giờ chúng ta hãy bắt đầu chuẩn bị để hôm kia nhé.', 'Korekara ''ototoi'' junbi o hajimemashou.'),
(36, '毎日「一昨年」練習を続けています。', 'Tôi duy trì việc luyện tập năm kia mỗi ngày.', 'Mainichi ''ototoshi'' renshuu o tsuzukete imasu.'),
(37, '新しい「伯母さん」を購入しました。', 'Tôi đã mua một bác mới.', 'Atarashii ''obasan'' o kounyuu shimashita.'),
(38, '「叔母さん」の使い方をマスターしましょう。', 'Hãy cùng nắm vững cách sử dụng của cô nhé.', '''obasan'' no tsukaikata o masukaa shimashou.'),
(39, '「そうして」は日常生活でよく使われます。', 'làm như thế thường xuyên được sử dụng trong đời sống hàng ngày.', '''soushite'' wa nichijou seikatsu de yoku tsukawaremasu.'),
(40, '毎日「作る」練習を続けています。', 'Tôi duy trì việc luyện tập chế biến mỗi ngày.', 'Mainichi ''tsukuru'' renshuu o tsuzukete imasu.'),
(41, '「円い」ものが好きです。', 'Tôi thích những thứ tròn.', '''marui'' mono ga suki desu.'),
(42, '今度の週末、久しぶりに高校の友達に会います。', 'Cuối tuần này, sau một thời gian dài tôi sẽ gặp lại bạn cấp ba.', 'Kondo no shuumatsu, hisashiburi ni koukou no tomodachi ni aimasu.'),
(43, 'その景色は本当に「青」と感じました。', 'Tôi cảm thấy khung cảnh đó thực sự rất màu xanh da trời.', 'Sono keshiki wa hontou ni ''ao'' to kanjimashita.'),
(44, 'この本はとても「青い」内容です。', 'Cuốn sách này có nội dung rất xanh da trời.', 'Kono hon wa totemo ''aoi'' naiyou desu.'),
(45, '新しい「赤」を購入しました。', 'Tôi đã mua một màu đỏ mới.', 'Atarashii ''aka'' o kounyuu shimashita.'),
(46, '今日はとても「赤い」天気ですね。', 'Hôm nay thời tiết thật là đỏ nhỉ.', 'Kyou wa totemo ''akai'' tenki desu ne.'),
(47, 'その景色は本当に「明い」と感じました。', 'Tôi cảm thấy khung cảnh đó thực sự rất sáng sủa.', 'Sono keshiki wa hontou ni ''akarui'' to kanjimashita.'),
