-- =============================================================================
-- Flyway Database Migration: V13__seed_kana_yoon_and_vocabulary_examples.sql
-- Module: Seed Bảng chữ cái âm ghép (Yōon) & Đảm bảo 100% từ vựng có ví dụ mẫu
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. SEED BẢNG CHỮ CÁI ÂM GHÉP (YŌON) - HIRAGANA (33 KÝ TỰ)
-- -----------------------------------------------------------------------------
ON CONFLICT (character) DO UPDATE SET romaji = EXCLUDED.romaji, meaning_vi = EXCLUDED.meaning_vi, char_type = EXCLUDED.char_type;

-- -----------------------------------------------------------------------------
-- 2. SEED BẢNG CHỮ CÁI ÂM GHÉP (YŌON) - KATAKANA (33 KÝ TỰ)
-- -----------------------------------------------------------------------------
ON CONFLICT (character) DO UPDATE SET romaji = EXCLUDED.romaji, meaning_vi = EXCLUDED.meaning_vi, char_type = EXCLUDED.char_type;

-- -----------------------------------------------------------------------------
-- 3. CẬP NHẬT CÂU VÍ DỤ SONG NGỮ CHO TOÀN BỘ 8,267 TỪ VỰNG
-- -----------------------------------------------------------------------------
CREATE TEMP TABLE IF NOT EXISTS temp_vocab_seed (
  vocab_id BIGINT PRIMARY KEY,
  example_jp TEXT,
  example_vi TEXT,
  example_romaji TEXT
);


















-- Cập nhật vào bảng vocabulary
UPDATE vocabulary v
SET example_jp = t.example_jp, example_vi = t.example_vi
FROM temp_vocab_seed t
WHERE v.id = t.vocab_id;

-- Cập nhật vào bảng vocabulary_examples
SELECT t.vocab_id, t.example_jp, t.example_vi, t.example_romaji, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM temp_vocab_seed t
WHERE NOT EXISTS (SELECT 1 FROM vocabulary_examples ve WHERE ve.vocab_id = t.vocab_id);

DROP TABLE IF EXISTS temp_vocab_seed;
